/* File security log: public.file_security_events, one row for each thing about an uploaded or downloaded file an admin may want to look back at: an upload refused (which check, what it found), an upload accepted with a note (an encrypted ZIP, a ZIP too large to list in time), a download refused, an upload or download refused for coming too often, an older file checked for the first time, a malware engine's verdict when one is switched on, and the admin test tool. Never a file's contents, never a secret, never a whole IP address (a short one way hash). /admin/security reads it; only the server writes it: row level security on, no policy, nothing granted to the browser. Also makes sure digital_assets has scan_status, scan_result and checksum (they are there on any database that ran the upload migrations or part 55; this only adds them where missing) and indexes the files from before the built-in checks, which the daily storage job checks a few at a time. Changes no rows. Safe after part 55, and safe without it. Needs nothing else. Until it runs, uploads and downloads work the same and the admin page says the log starts after this part. */
CREATE TABLE IF NOT EXISTS public.file_security_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), event text NOT NULL, outcome text NOT NULL, context text, code text, user_id uuid, creator_id uuid, asset_id uuid, bucket text, path text, file_name text, bytes bigint, detected_type text, sha256 text, provider text, detail jsonb, ip_hash text, CONSTRAINT file_security_events_outcome_check CHECK (outcome IN ('accepted', 'noted', 'refused', 'removed', 'denied', 'limited', 'info')));
CREATE INDEX IF NOT EXISTS file_security_events_created_idx ON public.file_security_events (created_at DESC);
CREATE INDEX IF NOT EXISTS file_security_events_outcome_idx ON public.file_security_events (outcome, created_at DESC) WHERE outcome <> 'info';
CREATE INDEX IF NOT EXISTS file_security_events_code_idx ON public.file_security_events (code, created_at DESC);
CREATE INDEX IF NOT EXISTS file_security_events_asset_idx ON public.file_security_events (asset_id) WHERE asset_id IS NOT NULL;
ALTER TABLE public.file_security_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.file_security_events FROM anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.digital_assets') IS NULL THEN RAISE NOTICE 'part 59: there is no digital_assets table, only the log was made.'; RETURN; END IF; ALTER TABLE public.digital_assets ADD COLUMN IF NOT EXISTS scan_status text DEFAULT 'pending_scan'; ALTER TABLE public.digital_assets ADD COLUMN IF NOT EXISTS scan_result jsonb; ALTER TABLE public.digital_assets ADD COLUMN IF NOT EXISTS checksum text; IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'digital_assets' AND column_name = 'created_at') THEN CREATE INDEX IF NOT EXISTS digital_assets_unchecked_idx ON public.digital_assets (created_at) WHERE scan_status IS NULL OR scan_status IN ('pending_scan', 'scanning'); END IF; END $do$;
notify pgrst, 'reload schema';
